{
 "wherefore": 1,
 "name": "fernhollow-kettles",
 "sources": {
  "facts": {
   "path": "facts.json",
   "adapter": "leaves",
   "why": "THE SOURCE: every fact the corpus states is here once"
  }
 },
 "generators": [
  {
   "script": "landing.py",
   "cwd": "gen",
   "makes": "site/index.html, the landing page"
  },
  {
   "script": "deck.py",
   "cwd": "gen",
   "makes": "deck/one-pager.svg, the one-page deck"
  },
  {
   "script": "notes.py",
   "cwd": "gen",
   "makes": "the speaker notes",
   "stdout_to": "deck/speaker-notes.txt"
  },
  {
   "script": "ledger.py",
   "cwd": "gen",
   "makes": "ledger.json, each document's edition"
  },
  {
   "run": [
    "python3",
    "-m",
    "wherefore",
    "graph",
    "--html",
    "-",
    "--json",
    "map/map.json"
   ],
   "cwd": ".",
   "makes": "map/map.json, what each generator reads and writes, which --since reads"
  }
 ],
 "not_a_generator": {},
 "inventory": {
  "note": "Every tracked file is generated, authored or captured. GENERATED is derived by running the generators; this declares the rest.",
  "authored": {
   "rules": [
    [
     "*.py",
     "code: the generators and the library they share"
    ],
    [
     "facts.json",
     "THE SOURCE"
    ],
    [
     "wherefore.json",
     "what the corpus is, and why each exemption exists"
    ],
    [
     "README.md",
     "prose a person writes"
    ],
    [
     ".gitignore",
     "what is never tracked: bytecode a generator's import leaves behind"
    ]
   ]
  },
  "captured": {
   "groups": {
    "the product photograph": {
     "files": [
      "photos/hero.svg"
     ],
     "why": "drawn by hand from the kettle on the bench; if the kettle's size moves, it has to be drawn again",
     "spec_values": [
      "product.capacity_l"
     ],
     "stamp": "b7725982e1a370ff"
    }
   }
  }
 },
 "proofs": {
  "glob": "proofs/*_proof.py"
 },
 "surfaces": {
  "read": {
   "include": [
    [
     "site",
     "*.html"
    ],
    [
     "deck",
     "*.svg"
    ],
    [
     "deck",
     "*.txt"
    ],
    [
     ".",
     "*.md"
    ]
   ],
   "skip": [],
   "archive": [
    "CHANGELOG"
   ],
   "why": "everything a customer or a buyer reads; code is not here - a literal in a generator is the reach probe's problem"
  }
 },
 "retired": {
  "register": {
   "source": "facts",
   "at": "retired"
  },
  "surface": "read",
  "assertion_patterns": [
   "\\$\\s*{v}(?!\\d|[.,]\\d)",
   "^\\s*{v}\\s*$"
  ],
  "exemptions": [],
  "why": "a fact goes stale as a number and a description goes stale as a sentence; both are read by the same person"
 },
 "reach": {
  "facts": {
   "source": "facts",
   "include": [
    "company.*",
    "product.*",
    "origin.activities.*"
   ],
   "exclude": [],
   "why": "every fact the corpus states; the origin note and the retired register are prose about the facts, read by people and by the retired check, never by a generator"
  },
  "watched": [
   "site",
   "deck"
  ],
  "exclude": [],
  "exempt": {},
  "unconsumed": {},
  "probes": [
   {
    "name": "the price",
    "fact": "product.price_usd",
    "reaches": "the page, the deck and the notes",
    "files": [
     "site/index.html",
     "deck/one-pager.svg",
     "deck/speaker-notes.txt"
    ]
   }
  ],
  "audience": "a customer"
 },
 "claims": [
  {
   "name": "the origin",
   "trigger": "in Portugal",
   "surface": "read",
   "may_say": {
    "assembled": "every kettle is assembled at the bench in Porto",
    "tested": "every kettle is boil-tested in Porto before it is boxed"
   },
   "never": {
    "made": "the heating element is bought in, so the kettle is not made in Portugal",
    "manufactured": "the same: the element is bought in",
    "produced": "the same: the element is bought in",
    "built": "the same: the element is bought in"
   },
   "why": "an origin claim has a regulated meaning; copy may name only what happens there"
  }
 ]
}

